import 'training_readiness_score.dart';

/// Comprehensive recovery intelligence report generated by RecoveryPredictionEngine.
class RecoveryReport {
  final String id;
  final String userId;
  final TrainingReadinessScore readinessScore;
  /// 'low', 'moderate', 'high', 'extreme', or 'unknown' when readiness is unavailable.
  final String fatigueLevel;
  final String recommendation; // Actionable training cue / advice
  final List<String> riskFactors;
  
  /// Workout history exists. Without it the load figures below describe
  /// nothing (they are zeros), and screens show dashes.
  final bool hasTrainingHistory;

  // Training Load Analytics
  final double acuteTrainingLoad; // ATL: 7-day cumulative load
  final double chronicTrainingLoad; // CTL: 28-day weekly average load
  final double acuteToChronicRatio; // ACWR: ATL / CTL (sweet spot 0.8 - 1.3)
  final double trainingStressBalance; // TSB: CTL - ATL (+ fresh, - fatigued)

  final bool isVolumeSpikeDetected; // ACWR > 1.5
  final bool isOvertrainingRisk;
  final bool isDeloadRecommended;
  final double suggestedVolumeAdjustmentPercent; // 0.0, -20.0, -50.0
  final DateTime generatedAt;

  const RecoveryReport({
    required this.id,
    required this.userId,
    required this.readinessScore,
    required this.fatigueLevel,
    required this.recommendation,
    this.riskFactors = const [],
    this.hasTrainingHistory = false,
    required this.acuteTrainingLoad,
    required this.chronicTrainingLoad,
    required this.acuteToChronicRatio,
    required this.trainingStressBalance,
    required this.isVolumeSpikeDetected,
    required this.isOvertrainingRisk,
    required this.isDeloadRecommended,
    required this.suggestedVolumeAdjustmentPercent,
    required this.generatedAt,
  });

  /// Plain English answer to "Should this athlete train hard today?"
  String get trainHardAnswer {
    if (!readinessScore.isAvailable) {
      return 'Can\'t tell yet: ${readinessScore.explanation}';
    }
    if (readinessScore.score >= 80.0) {
      return 'Yes! Athlete is primed for peak intensity and progressive overload.';
    } else if (readinessScore.score >= 70.0) {
      return 'Yes, ready for planned training with normal volume.';
    } else if (readinessScore.score >= 50.0) {
      return 'Train with caution: Maintain load but reduce total volume sets by 20%.';
    } else {
      return 'No: High systemic fatigue. Prioritize recovery, mobility, or light cardio today.';
    }
  }

  factory RecoveryReport.fromJson(Map<String, dynamic> json) {
    return RecoveryReport(
      id: json['id'] as String? ?? '',
      userId: json['userId'] as String? ?? 'usr_local',
      readinessScore: TrainingReadinessScore.fromJson(
        json['readinessScore'] as Map<String, dynamic>? ?? {},
      ),
      fatigueLevel: json['fatigueLevel'] as String? ?? 'unknown',
      hasTrainingHistory: json['hasTrainingHistory'] as bool? ?? false,
      recommendation: json['recommendation'] as String? ?? '',
      riskFactors: (json['riskFactors'] as List<dynamic>?)?.map((e) => e as String).toList() ?? const [],
      acuteTrainingLoad: (json['acuteTrainingLoad'] as num? ?? 0.0).toDouble(),
      chronicTrainingLoad: (json['chronicTrainingLoad'] as num? ?? 0.0).toDouble(),
      acuteToChronicRatio: (json['acuteToChronicRatio'] as num? ?? 1.0).toDouble(),
      trainingStressBalance: (json['trainingStressBalance'] as num? ?? 0.0).toDouble(),
      isVolumeSpikeDetected: json['isVolumeSpikeDetected'] as bool? ?? false,
      isOvertrainingRisk: json['isOvertrainingRisk'] as bool? ?? false,
      isDeloadRecommended: json['isDeloadRecommended'] as bool? ?? false,
      suggestedVolumeAdjustmentPercent: (json['suggestedVolumeAdjustmentPercent'] as num? ?? 0.0).toDouble(),
      generatedAt: json['generatedAt'] != null ? DateTime.parse(json['generatedAt'] as String) : DateTime.now(),
    );
  }

  Map<String, dynamic> toJson() => {
    'id': id,
    'userId': userId,
    'readinessScore': readinessScore.toJson(),
    'fatigueLevel': fatigueLevel,
    'recommendation': recommendation,
    'riskFactors': riskFactors,
    'hasTrainingHistory': hasTrainingHistory,
    'acuteTrainingLoad': acuteTrainingLoad,
    'chronicTrainingLoad': chronicTrainingLoad,
    'acuteToChronicRatio': acuteToChronicRatio,
    'trainingStressBalance': trainingStressBalance,
    'isVolumeSpikeDetected': isVolumeSpikeDetected,
    'isOvertrainingRisk': isOvertrainingRisk,
    'isDeloadRecommended': isDeloadRecommended,
    'suggestedVolumeAdjustmentPercent': suggestedVolumeAdjustmentPercent,
    'generatedAt': generatedAt.toIso8601String(),
  };
}
